/* Local teaching workflow; never used as official student records or authorization. */
const WORK_KEY='scholarion-course-work-v1';
let courseWork={};try{courseWork=JSON.parse(localStorage.getItem(WORK_KEY)||'{}');}catch{}
function workRecord(id){return courseWork[id]||(courseWork[id]={attempts:{},reviews:{},posts:[],start:'',audit:[]});}
function workSave(){localStorage.setItem(WORK_KEY,JSON.stringify(courseWork));}
function workEvent(p,action){workRecord(p.id).audit.push({at:new Date().toISOString(),action});workSave();}
function workPage(p,selected){const w=workRecord(p.id),a=p.assessments.find(x=>x.id===selected)||p.assessments[0],attempts=w.attempts[a.id]||[],latest=attempts.at(-1),review=w.reviews[a.id],visible=CourseWork.visibleGrade(review,latest),staff=academyStaff();return heading('Course work · Program '+p.id,p.title,btn('Program syllabus','#academy/'+p.id,true))+`<div class="callout">Practice workspace. Text submissions, attempts and feedback persist on this browser. Role selection is a preview, not authenticated access. No official grades or credentials are awarded here.</div><div class="academy-module-grid"><aside class="card prose"><h2>Assignments</h2><label>Choose assessment<select id="work-assignment" data-program="${p.id}">${p.assessments.map(x=>`<option value="${esc(x.id)}" ${x.id===a.id?'selected':''}>${esc(x.id)} · ${esc(x.type)}</option>`).join('')}</select></label><h3>Suggested pacing</h3><form id="work-pacing" data-program="${p.id}"><label>Start date<input name="start" type="date" value="${esc(w.start)}" required></label><button class="button secondary">Reset suggested dates</button></form><p>Dates are suggestions and use calendar days. Resetting does not alter submission history.</p>${w.start?`<p>Suggested completion: <b>${CourseWork.dueDate(w.start,p.modules[a.module-1].proposedWeek)}</b></p>`:''}<p>${btn('Discussion and peer feedback','#course-discussion/'+p.id,true)}</p><p>${btn('Grades and What-If','#course-grades/'+p.id,true)}</p><button class="button secondary" data-work-export="${p.id}">Export course work</button></aside><article class="card prose"><h2>${esc(a.id)}</h2><p>${esc(a.brief)}</p>${listHTML(a.steps)}<p>${esc(a.aiPolicy)}</p><h3>Submit your work</h3><form id="work-submit" data-program="${p.id}" data-assignment="${esc(a.id)}"><label>Written submission<textarea name="text" rows="8" maxlength="20000" required></textarea></label><button class="button">Save submission attempt</button></form><h3>Attempt history</h3>${attempts.slice().reverse().map(t=>`<details><summary>Attempt ${t.number} · ${esc(new Date(t.submittedAt).toLocaleString())}</summary><p>Receipt: ${esc(t.id)}</p><pre style="white-space:pre-wrap">${esc(t.text)}</pre></details>`).join('')||'<p>No submissions yet.</p>'}<h3>Released feedback</h3>${visible?`<p><b>${visible.score}/100</b></p><p>${esc(visible.feedback)}</p>`:'<p>No posted feedback for the current attempt.</p>'}${staff&&latest?`<h3>Instructor preview · Review attempt ${latest.number}</h3><form id="work-grade" data-program="${p.id}" data-assignment="${esc(a.id)}"><label>Score out of 100<input name="score" type="number" min="0" max="100" step="0.1" required value="${review?.attemptId===latest.id?review.score:''}"></label><label>Feedback<textarea name="feedback" required maxlength="5000">${esc(review?.attemptId===latest.id?review.feedback:'')}</textarea></label><button class="button">Save unposted review</button></form>${review?.attemptId===latest.id?`<p>Status: ${review.posted?'Posted':'Hidden from learner preview'}</p><button class="button secondary" data-work-post="${esc(a.id)}" data-program="${p.id}">${review.posted?'Hide feedback':'Post feedback'}</button>`:''}`:''}</article></div>`+academyRubric(p);}
function workGrades(p){const w=workRecord(p.id);return heading('Practice grades and What-If',p.title,btn('Course work','#course-work/'+p.id,true))+`<section class="card prose"><p>Only posted scores for current attempts appear here. Hypothetical scores stay in this page and never modify saved reviews. This is an unweighted practice average, not the official program grade.</p><div class="table-scroll"><table><thead><tr><th>Assessment</th><th>Submission</th><th>Posted score</th><th>What-If /100</th></tr></thead><tbody>${p.assessments.map(a=>{const ts=w.attempts[a.id]||[],r=CourseWork.visibleGrade(w.reviews[a.id],ts.at(-1));return `<tr><td><a href="#course-work/${p.id}/${a.id}">${esc(a.id)}</a></td><td>${ts.length?'Attempt '+ts.length:'Not submitted'}</td><td>${r?r.score:'—'}</td><td><input class="work-whatif" aria-label="Hypothetical score for ${esc(a.id)}" type="number" min="0" max="100" step="0.1" data-score="${r?r.score:''}"></td></tr>`;}).join('')}</tbody></table></div><p id="work-average" role="status">Enter hypothetical scores to calculate a practice average.</p></section>`;}
function workDiscussion(p){const w=workRecord(p.id);return heading('Discussion and peer feedback',p.title,btn('Course work','#course-work/'+p.id,true))+`<section class="card prose"><p>Explain one design tradeoff in your ${esc(p.capstone)}. Ask for evidence, compare the baseline and suggest a test. This is a single-browser discussion rehearsal; it does not send messages to other learners.</p><form id="work-discussion" data-program="${p.id}"><label>Reply to<select name="parent"><option value="">New topic</option>${w.posts.filter(x=>!x.parent).map(x=>`<option value="${x.id}">${esc(x.text.slice(0,80))}</option>`).join('')}</select></label><label>Your contribution<textarea name="text" required maxlength="3000"></textarea></label><button class="button">Save contribution</button></form>${w.posts.filter(x=>!x.parent).map(x=>`<article class="callout"><p>${esc(x.text)}</p><small>${esc(new Date(x.at).toLocaleString())}</small>${w.posts.filter(y=>y.parent===x.id).map(y=>`<blockquote>${esc(y.text)}</blockquote>`).join('')}</article>`).join('')}</section>`;}
const beforeCourseWork=render;render=function(){const [route,id,assignment]=location.hash.slice(1).split('/'),p=academyProgram(id);if(['course-work','course-grades','course-discussion'].includes(route)&&p){document.getElementById('app').innerHTML=integratedShell(route,route==='course-work'?workPage(p,assignment):route==='course-grades'?workGrades(p):workDiscussion(p),model.role);decorateRole(model.role);bind();}else beforeCourseWork();if(route==='academy'&&p)document.querySelector('main')?.insertAdjacentHTML('afterbegin',`<p>${btn('Open course work, submissions and feedback','#course-work/'+p.id)}</p>`);};
document.addEventListener('change',e=>{if(e.target.id==='work-assignment')location.hash='course-work/'+e.target.dataset.program+'/'+e.target.value;});
document.addEventListener('input',e=>{if(!e.target.matches('.work-whatif'))return;const inputs=[...document.querySelectorAll('.work-whatif')];if(inputs.some(x=>!x.validity.valid)){document.getElementById('work-average').textContent='Use scores between 0 and 100.';return;}const values=inputs.map(x=>x.value===''?x.dataset.score:x.value).filter(x=>x!=='').map(Number),avg=CourseWork.average(values);document.getElementById('work-average').textContent=avg===null?'No scores to average.':`Practice average: ${avg.toFixed(1)}% across ${values.length} scored items.`;});
document.addEventListener('submit',e=>{const f=e.target;if(!['work-submit','work-grade','work-pacing','work-discussion'].includes(f.id))return;e.preventDefault();const p=academyProgram(f.dataset.program),w=workRecord(p.id),v=new FormData(f),key=f.dataset.assignment;try{if(f.id==='work-submit')w.attempts[key]=CourseWork.submit(w.attempts[key]||[],v.get('text'),new Date().toISOString());if(f.id==='work-grade'){if(!academyStaff())throw Error('Switch to the instructor preview to grade.');w.reviews[key]=CourseWork.grade(w.reviews[key],w.attempts[key]?.at(-1),Number(v.get('score')),v.get('feedback'),new Date().toISOString());}if(f.id==='work-pacing'){CourseWork.dueDate(v.get('start'),1);w.start=v.get('start');}if(f.id==='work-discussion'){const text=v.get('text').trim(),parent=v.get('parent');if(!text||text.length>3000)throw Error('Enter a contribution');if(parent&&!w.posts.some(x=>x.id===parent&&!x.parent))throw Error('Topic no longer exists');w.posts.push({id:crypto.randomUUID(),parent,text,at:new Date().toISOString()});}workEvent(p,f.id);render();toast('Saved on this browser.');}catch(err){toast(err.message);}});
document.addEventListener('click',e=>{const t=e.target.closest('[data-work-post],[data-work-export]');if(!t)return;if(t.dataset.workExport){download('scholarion-course-'+t.dataset.workExport+'-practice.json',JSON.stringify(workRecord(t.dataset.workExport),null,2),'application/json');return;}if(!academyStaff())return;const p=academyProgram(t.dataset.program),w=workRecord(p.id),r=w.reviews[t.dataset.workPost];if(r&&r.attemptId===w.attempts[t.dataset.workPost]?.at(-1)?.id){r.posted=!r.posted;workEvent(p,(r.posted?'Post ':'Hide ')+t.dataset.workPost);render();}});
render();
